1	#!/usr/bin/env node
2	// World-scope conformance runner (see DESIGN.md): the rules that audit repo
3	// state as it exists now, plus the pack-agnostic settings/load integrity
4	// diagnostics (malformed config, an unknown pack, a broken pack.mjs). Rules that
5	// judge the current change (`scope: 'work'`) run in check_the_work.mjs, which
6	// this file shares no code with — only the scope-blind mechanism helpers
7	// (run-active-pack-rules.mjs, report-findings.mjs). It names NO pack: adoption
8	// interview hygiene is a skill-owned check that rides its own pack's activation,
9	// and a malformed `questions` field is a load fault the pack registry reports.
10	// Wired into the project's test/CI flow, not the Stop hook. Dependency-free Node ≥18.
11	//   (default)   whole-repo sweep — milliseconds on a text corpus, sees cross-file breakage
12	//   --changed   transitional: scope to files changed vs the merge-base with main
13	//               (adopting a repo with a backlog only — not the enforcement default)
14	//   --base REF  override the base ref
15	//   --list      machine-readable catalog of every rule, both scopes (id, severity, description, doc)
16	//   --init      write .claudinite-checks.json — basics plus the fingerprinted packs
17	import { writeFileSync, existsSync } from 'node:fs';
18	import { join } from 'node:path';
19	import { buildContext } from './helpers/repo-context.mjs';
20	import { discoverPacks, resolveDeclaredPacks } from '../pack_loader/pack-registry.mjs';
21	import { runActivePackRules, packRules } from './run-active-pack-rules.mjs';
22	import { reportFindings } from './report-findings.mjs';
23	
24	const configError = (what, fix) => ({
25	  rule: 'config', severity: 'blocking', file: '.claudinite-checks.json', line: null,
26	  what, why: 'the settings file is what executes — a bad key, value, or pack name silently changes what runs', fix, doc: 'engine/checks/README.md',
27	});
28	
29	const args = process.argv.slice(2);
30	const has = (flag) => args.includes(flag);
31	const value = (flag) => (args.includes(flag) ? args[args.indexOf(flag) + 1] : null);
32	const root = value('--root') || process.cwd();
33	
34	if (has('--list')) {
35	  const { packs } = await discoverPacks({ localRoot: root });
36	  for (const r of packRules(packs)) {
37	    console.log(`${r.id}\t${r.severity}\t${r.description}\t${r.doc}`);
38	  }
39	  process.exit(0);
40	}
41	
42	if (has('--init')) {
43	  const path = join(root, '.claudinite-checks.json');
44	  if (existsSync(path)) {
45	    console.log(`${path} already exists — leaving it as-is.`);
46	    process.exit(0);
47	  }
48	  const { packs } = await discoverPacks({ localRoot: root });
49	  const ctx = buildContext({ root, mode: 'all' });
50	  // No pack is active by default, so the baseline is seeded as an explicit
51	  // declaration alongside the fingerprinted packs: every pack that flags
52	  // `seededByDefault` is written in (discovered structurally — the engine names
53	  // no pack), plus the ones a fingerprint detects. A seeded pack is still
54	  // opt-out-able where its own policy allows (baselining re-adds only the packs
55	  // whose absence it treats as drift), so removing a seeded declaration can
56	  // stick; each seeded pack ships its own one-time seed migration for the fleet.
57	  // Local packs are declared by hand, never fingerprinted or seeded — exclude
58	  // them from --init's seeding so a repo that already carries local packs (but
59	  // no config yet) doesn't auto-declare them.
60	  const seeded = packs.filter((p) => p.seededByDefault && !p.local).map((p) => p.id);
61	  const detected = [...seeded, ...packs.filter((p) => p.detect && !p.local && p.detect(ctx)).map((p) => p.id)];
62	  // A pack can't be imported without its dependencies — pull each declared pack's
63	  // `requires` closure into the declaration so it's complete and visible.
64	  const declared = resolveDeclaredPacks(detected, packs);
65	  // maintenance.delivery is deliberately materialized, not defaulted — the selection
66	  // must be visible in the file where a project would change it (see engine/checks/README.md).
67	  // Only what carries a decision: the declaration and the always-explicit
68	  // delivery. Empty rules/accept boilerplate is noise, not settings (#385);
69	  // loadConfig defaults absent keys.
70	  writeFileSync(path, `${JSON.stringify({ packs: declared, maintenance: { delivery: 'auto-merge' } }, null, 2)}\n`);
71	  console.log(`Wrote ${path} (packs: ${declared.join(', ')}).`);
72	  // The adoption interview (surfacing each declared pack's pending questions) is
73	  // driven by the adopt-claudinite skill / bootstrap.md, and nudged every session
74	  // by the SessionStart interview-check step — not printed here, so this runner
75	  // imports no pack.
76	  process.exit(0);
77	}
78	
79	const { packs, errors: packErrors } = await discoverPacks({ localRoot: root });
80	const ctx = buildContext({ root, mode: has('--changed') ? 'changed' : 'all', baseOverride: value('--base') });
81	
82	// Settings/load integrity — pack-agnostic, so the world runner owns them.
83	// Settings validity is checked at load: malformed JSON, an unknown
84	// property, and a wrong pack name are all equally settings errors. loadConfig
85	// reports the first two; the runner adds unknown pack names (only it holds the
86	// registry) and broken/duplicate local pack.mjs faults.
87	const findings = [];
88	for (const e of ctx.config.errors) findings.push(configError(e.what, e.fix));
89	for (const e of packErrors) findings.push(configError(e.what, e.fix));
90	// knownIds spans canon AND local packs, so a declared local pack id is valid and
91	// the unknown-pack message lists it among the declarable packs. ctx.config.packs
92	// is loadConfig's normalized view — bare ids, a namespaced local_packs/<name>
93	// declaration already resolved through packEntryId.
94	const knownIds = new Set(packs.map((p) => p.id));
95	for (const name of ctx.config.packs) {
96	  if (typeof name === 'string' && !knownIds.has(name)) {
97	    findings.push(configError(`declares unknown pack "${name}"`, `remove it or fix the name — declarable packs: ${[...knownIds].sort().join(', ')}`));
98	  }
99	}
100	// (Adoption-interview hygiene is a skill-owned check that runs below with the
101	// other active-pack rules; a malformed `questions` field arrives as a load fault
102	// in packErrors above. Neither names a pack here.)
103	
104	// The world rules: everything not scoped to the work. A broken contributedRules
105	// seam is a config-level fault surfaced here (the world runner owns diagnostics).
106	findings.push(...runActivePackRules(ctx, packs, {
107	  includeRule: (rule) => rule.scope !== 'work',
108	  onContributeError: (pack, e) => findings.push(configError(
109	    `the "${pack.id}" pack's contributedRules failed: ${e.message}`, 'fix the pack manifest, or the contribution it interprets')),
110	}));
111	
112	const blocking = reportFindings(findings, ctx.config, { scopeLabel: 'world', mode: ctx.mode, baseRef: ctx.baseRef });
113	process.exit(blocking ? 1 : 0);
114

1	#!/usr/bin/env node
2	// Work-scope conformance runner (see DESIGN.md): the rules that judge the
3	// current change — the branch's diff against the merge-base, and (at Stop) the
4	// session transcript — each declaring `scope: 'work'` and receiving the fluent
5	// work view (helpers/work.mjs). Repo-state rules and settings diagnostics run in
6	// check_the_world.mjs, which this file shares no code with (only the scope-blind
7	// mechanism helpers). The Stop hook runs this; CI runs the world runner.
8	//   --transcript PATH   the session transcript — conversation rules self-skip without it
9	//   --changed / --base REF / --root DIR   as in check_the_world.mjs
10	import { buildContext } from './helpers/repo-context.mjs';
11	import { discoverPacks } from '../pack_loader/pack-registry.mjs';
12	import { runActivePackRules } from './run-active-pack-rules.mjs';
13	import { reportFindings } from './report-findings.mjs';
14	
15	const args = process.argv.slice(2);
16	const has = (flag) => args.includes(flag);
17	const value = (flag) => (args.includes(flag) ? args[args.indexOf(flag) + 1] : null);
18	const root = value('--root') || process.cwd();
19	
20	const { packs } = await discoverPacks({ localRoot: root });
21	const ctx = buildContext({
22	  root,
23	  mode: has('--changed') ? 'changed' : 'all',
24	  baseOverride: value('--base'),
25	  transcriptPath: value('--transcript'),
26	});
27	
28	const findings = runActivePackRules(ctx, packs, { includeRule: (rule) => rule.scope === 'work' });
29	const blocking = reportFindings(findings, ctx.config, { scopeLabel: 'work', mode: ctx.mode, baseRef: ctx.baseRef });
30	process.exit(blocking ? 1 : 0);
31

1	import { dirname, join, normalize } from 'node:path';
2	import { humanTurns, assistantTextAfter, classificationLine, classesIn } from './session-transcript.mjs';
3	import { addedLines } from './line-scanning.mjs';
4	import { extractLinks } from './markdown.mjs';
5	
6	// The fluent check-the-work surface over ctx. Every accessor is null-safe — no
7	// transcript, no merge-base, an empty branch all yield empty results — so a rule
8	// reads as one chain with no guard ladders. Mechanism only: a rule still owns
9	// its patterns, file filters, and failure text.
10	//
11	// A rule declaring `scope: 'work'` receives this object as its `run` argument
12	// (runRule dispatches); check-the-world rules keep the raw ctx until a fluent
13	// world object exists. The raw surface a work rule still needs (files, read,
14	// exists, …) is delegated here, so a work rule — and the structural helpers it
15	// calls, e.g. findExtensionManifest — never touches ctx itself.
16	export const work = (ctx) => new Work(ctx);
17	
18	// The single dispatch seam: the runner and every rule test invoke rules through
19	// this, so a rule's scope decides its context in exactly one place. Extra args
20	// pass through (some rules take test-only options after the context).
21	export const runRule = (rule, ctx, ...args) => rule.run(rule.scope === 'work' ? work(ctx) : ctx, ...args);
22	
23	// Null-object for "no such turn": every accessor answers emptily, so a chain
24	// ending in .last() never needs an existence guard before its predicates.
25	const NO_TURN = {
26	  exists: false, text: '', timestamp: null,
27	  excerpt: () => '', reply: () => '', classified: () => false,
28	  classes: () => new Set(), time: () => 0,
29	};
30	
31	class Turn {
32	  constructor(entries, { index, timestamp, text }) {
33	    this.entries = entries;
34	    this.index = index;
35	    this.timestamp = timestamp;
36	    this.text = text;
37	    this.exists = true;
38	  }
39	
40	  excerpt(n) { return this.text.replace(/\s+/g, ' ').slice(0, n); }
41	  reply() { return assistantTextAfter(this.entries, this.index); }
42	  classified() { return classificationLine(this.reply()) !== null; }
43	  classes() { return classesIn(classificationLine(this.reply())); }
44	  time() { return Date.parse(this.timestamp ?? '') || 0; }
45	}
46	
47	// Array subclass so filter/map stay chainable and .last() survives them.
48	class Turns extends Array {
49	  last() { return this.length ? this[this.length - 1] : NO_TURN; }
50	}
51	
52	class Conversation {
53	  constructor(entries) { this.entries = entries ?? []; }
54	
55	  ownerTurns() {
56	    const turns = new Turns();
57	    for (const t of humanTurns(this.entries)) turns.push(new Turn(this.entries, t));
58	    return turns;
59	  }
60	}
61	
62	class Work {
63	  constructor(ctx) { this.ctx = ctx; }
64	
65	  get branch() { return this.ctx.branch; }
66	  get baseRef() { return this.ctx.baseRef; }
67	  get commits() { return this.ctx.commits; }
68	  get files() { return this.ctx.files; }
69	  get changedFiles() { return this.ctx.changedFiles; }
70	  get tracked() { return this.ctx.tracked; }
71	  // The discovered pack objects (runner-attached) and the normalized config —
72	  // the pair a rule that reasons over pack metadata (e.g. adoption-interview
73	  // state) hands to the interview helpers, without reaching into ctx itself.
74	  get packs() { return this.ctx.packs ?? []; }
75	  get config() { return this.ctx.config; }
76	  read(path) { return this.ctx.read(path); }
77	  readBase(path) { return this.ctx.readBase(path); }
78	  exists(path) { return this.ctx.exists(path); }
79	  packConfig(id) { return this.ctx.config?.packConfig?.[id]; }
80	
81	  conversation() { return new Conversation(this.ctx.conversation()); }
82	
83	  addedLines(files) { return addedLines(this.ctx, files ?? this.ctx.changedFiles); }
84	
85	  onDefaultBranch() { return this.ctx.branch === 'main' || this.ctx.branch === 'master'; }
86	
87	  introducedMerges() { return this.ctx.introducedMergeCommits(); }
88	
89	  // Branch commits since the merge-base, oldest first, each with a parsed .time.
90	  branchCommits() {
91	    return this.ctx.commitsWithFiles().map((c) => ({ ...c, time: Date.parse(c.date) || 0 }));
92	  }
93	
94	  // `file` parsed as JSON at head and at the scoping base; a side that is
95	  // absent or unparsable is null, so set-vs-base rules need no try/catch.
96	  jsonPair(file) {
97	    const parse = (text) => {
98	      if (text === null) return null;
99	      try { return JSON.parse(text); } catch { return null; }
100	    };
101	    return { head: parse(this.ctx.read(file)), base: parse(this.ctx.readBase(file)) };
102	  }
103	
104	  filesContaining(needle, files = this.ctx.files) {
105	    return files.filter((f) => (this.ctx.read(f) ?? '').includes(needle));
106	  }
107	
108	  // Relative Markdown links that resolve to nothing: [{ file, line, target, resolved }].
109	  // Links reaching outside the repo aren't verifiable here and are skipped.
110	  deadLinks(files) {
111	    const out = [];
112	    for (const file of (files ?? this.ctx.files).filter((f) => f.endsWith('.md'))) {
113	      const text = this.ctx.read(file);
114	      if (text === null) continue;
115	      for (const { target, line } of extractLinks(text)) {
116	        const resolved = normalize(join(dirname(file), target));
117	        if (resolved.startsWith('..') || this.ctx.exists(resolved)) continue;
118	        out.push({ file, line, target, resolved });
119	      }
120	    }
121	    return out;
122	  }
123	
124	  // Tracked lines still naming a path this change deletes: [{ file, line, text, gone }].
125	  // A hit whose every occurrence widens to a path token that still resolves is a
126	  // rename that kept the basename, not a dangling reference — dropped. `tolerated(gone)`
127	  // lets the rule exempt paths something else deliberately governs.
128	  danglingReferences(tolerated = () => false) {
129	    const out = [];
130	    for (const gone of this.ctx.deleted) {
131	      if (tolerated(gone)) continue;
132	      for (const hit of this.ctx.grepTracked(gone)) {
133	        if (hit.file === gone || referencesSurvivingPath(hit, gone, this.ctx)) continue;
134	        out.push({ ...hit, gone });
135	      }
136	    }
137	    return out;
138	  }
139	}
140	
141	const PATH_CHAR = /[\w./@-]/;
142	
143	function widenToken(text, start, end) {
144	  let s = start;
145	  let e = end;
146	  while (s > 0 && PATH_CHAR.test(text[s - 1])) s--;
147	  while (e < text.length && PATH_CHAR.test(text[e])) e++;
148	  return text.slice(s, e);
149	}
150	
151	function referencesSurvivingPath(hit, gone, ctx) {
152	  let idx = hit.text.indexOf(gone);
153	  if (idx === -1) return false;
154	  while (idx !== -1) {
155	    const token = widenToken(hit.text, idx, idx + gone.length);
156	    const resolved = normalize(join(dirname(hit.file), token));
157	    if (!((token !== gone && ctx.exists(token)) || ctx.exists(resolved))) return false;
158	    idx = hit.text.indexOf(gone, idx + 1);
159	  }
160	  return true;
161	}
162

1	import { finding } from '../../engine/checks/helpers/findings.mjs';
2	
3	// Only the latest owner comment is judged: earlier turns were judged at their
4	// own Stops, and a transcript is append-only, so an old omission never converges.
5	const rule = {
6	  id: 'comment-classification',
7	  severity: 'blocking',
8	  description: 'The reply to the owner\'s latest comment must declare an explicit `Comment class:` line',
9	  doc: 'packs/basics/RULES.md',
10	  scope: 'work',
11	  why: 'the class decides the flow (correction / feature / process-change); an unclassified comment tends to become an unrouted one-off patch',
12	
13	  run(work) {
14	    const lastOwnerTurn = work.conversation().ownerTurns().last();
15	    if (!lastOwnerTurn.exists || lastOwnerTurn.classified()) return [];
16	    return [finding(rule, {
17	      file: '(conversation)',
18	      what: `the reply to the owner's latest comment ("${lastOwnerTurn.excerpt(70)}…") declares no \`Comment class:\` line`,
19	      fix: 'state the classification explicitly — emit a line `Comment class: correction | feature | process-change | other` (a mixed comment names each part) in your reply text',
20	    })];
21	  },
22	};
23	
24	export default rule;
